def ip_lookup(api_key, ip, refresh=None, **_extra):
    import json, os, datetime, time, re, ipaddress, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0119000" if __import__("os").path.isdir("./environment_mix/0119000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _canonical_ip(s):
        try:
            ipobj = ipaddress.ip_address(s.strip())
            return ipobj.compressed, ("ipv6" if ipobj.version == 6 else "ipv4")
        except Exception:
            return None, None

    def _pick_api_key(keys, api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        # Authenticate by client-visible value: accept either stored id or stored key_prefix.
        for k in keys:
            if k.get("id") == v:
                return k
        for k in keys:
            if k.get("key_prefix") == v:
                return k
        return None

    def _quota_check_and_log(tool_name, api_key_row, params, status, latency_ms=None, cache_hit=False, normalized_query=None, result_summary=None, error_code=None, error_message=None):
        tool_requests = _load("tool_requests.json")
        now = _now_utc()
        req_id = _new_id("tr")

        row = {
            "id": req_id,
            "api_key_id": api_key_row["id"],
            "tool_name": tool_name,
            "status": "queued",
            "request_params": params if isinstance(params, dict) else {},
            "normalized_query": normalized_query,
            "result_summary": result_summary,
            "error_code": None,
            "error_message": None,
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": bool(cache_hit),
            "latency_ms": latency_ms,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tool_requests.append(row)

        allowed = {"queued": ["running", "failed", "rate_limited"], "running": ["succeeded", "failed", "rate_limited"]}
        def _set_status(new_status, ecode=None, emsg=None, cache_hit_val=None, latency=None, summary=None):
            cur = row["status"]
            if cur in ("succeeded", "failed", "rate_limited"):
                return False
            if cur in allowed and new_status in allowed[cur]:
                row["status"] = new_status
                row["updated_at"] = _iso(_now_utc())
                if ecode is not None:
                    row["error_code"] = ecode
                if emsg is not None:
                    row["error_message"] = emsg[:4000] if isinstance(emsg, str) else emsg
                if cache_hit_val is not None:
                    row["cache_hit"] = bool(cache_hit_val)
                if latency is not None:
                    row["latency_ms"] = int(latency) if isinstance(latency, int) and latency >= 0 else latency
                if summary is not None:
                    row["result_summary"] = summary
                return True
            return False

        # Evaluate rate limit/quota for this request BEFORE performing work, but after logging row.
        # If api key not active -> rate_limited (business rule).
        if api_key_row.get("status") != "active":
            _set_status("rate_limited", ecode="UNAUTHORIZED", emsg="API key is not active.", cache_hit_val=False, latency=0, summary={"reason": "inactive_key"})
            _save("tool_requests.json", tool_requests)
            return row, _err("RATE_LIMIT", "API key is not active.")

        rpm = api_key_row.get("requests_per_minute")
        rpd = api_key_row.get("requests_per_day")
        if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
            _set_status("failed", ecode="VALIDATION_ERROR", emsg="API key quota configuration invalid.", cache_hit_val=False, latency=0)
            _save("tool_requests.json", tool_requests)
            return row, _err("UNAUTHORIZED", "API key quota configuration invalid.")

        # Count prior requests in rolling minute and UTC day for this api_key_id.
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        used_min = 0
        used_day = 0
        for r in tool_requests:
            if r.get("api_key_id") != api_key_row["id"]:
                continue
            ca = _parse_dt(r.get("created_at"))
            if not ca:
                continue
            if ca >= one_min_ago:
                used_min += 1
            if ca >= day_start and ca <= now:
                used_day += 1

        # Include current request (already appended) in the counts above.
        if used_min > rpm:
            _set_status("rate_limited", ecode="RATE_LIMIT", emsg="Per-minute rate limit exceeded.", cache_hit_val=False, latency=0, summary={"limit": rpm, "used_last_minute": used_min})
            _save("tool_requests.json", tool_requests)
            return row, _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=rpm, used_last_minute=used_min)
        if used_day > rpd:
            _set_status("rate_limited", ecode="QUOTA_EXCEEDED", emsg="Daily request quota exceeded.", cache_hit_val=False, latency=0, summary={"limit": rpd, "used_today": used_day})
            _save("tool_requests.json", tool_requests)
            return row, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd, used_today=used_day)

        # mark running and persist
        _set_status("running")
        _save("tool_requests.json", tool_requests)
        return row, None

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(ip, str) or not ip.strip():
        return _err("VALIDATION_ERROR", "ip must be a non-empty string.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean if provided.")

    keys = _load("api_keys.json")
    key_row = _pick_api_key(keys, api_key)
    if not key_row:
        # Can't log without api_key_id reference.
        return _err("UNAUTHORIZED", "Invalid API key.")

    canon_ip, ip_version = _canonical_ip(ip)
    if not canon_ip:
        # log as failed (we do have api key)
        tool_requests = _load("tool_requests.json")
        now = _now_utc()
        rid = _new_id("tr")
        tool_requests.append({
            "id": rid,
            "api_key_id": key_row["id"],
            "tool_name": "ip_lookup",
            "status": "failed",
            "request_params": {"api_key": api_key, "ip": ip, "refresh": refresh},
            "normalized_query": None,
            "result_summary": None,
            "error_code": "VALIDATION_ERROR",
            "error_message": "Invalid IP address.",
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": False,
            "latency_ms": 0,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("tool_requests.json", tool_requests)
        return _err("VALIDATION_ERROR", "Invalid IP address.")

    # Rate limit + create tool_requests row
    params = {"api_key": api_key, "ip": ip, "refresh": refresh}
    tr_row, quota_err = _quota_check_and_log(
        "ip_lookup",
        key_row,
        params,
        status=None,
        normalized_query=canon_ip,
        cache_hit=False,
    )
    if quota_err:
        return quota_err

    # Perform lookup from cache; refresh if needed
    hosts = _load("hosts.json")
    now = _now_utc()

    host_row = None
    for h in hosts:
        if h.get("ip") == canon_ip:
            host_row = h
            break

    def _is_fresh(hrow):
        if not hrow:
            return False
        if hrow.get("status") != "fresh":
            return False
        exp = _parse_dt(hrow.get("expires_at"))
        return bool(exp and exp > now)

    force_refresh = bool(refresh)
    cache_hit = False

    if host_row and _is_fresh(host_row) and not force_refresh:
        cache_hit = True
        # success; update request + key last_used_at
        latency = int((time.time() - t0) * 1000)
        tool_requests = _load("tool_requests.json")
        # update status for this request
        for r in tool_requests:
            if r.get("id") == tr_row["id"]:
                # running -> succeeded
                r["status"] = "succeeded"
                r["cache_hit"] = True
                r["latency_ms"] = latency
                r["result_summary"] = {"cache": "hit", "ip": canon_ip}
                r["updated_at"] = _iso(_now_utc())
                break
        _save("tool_requests.json", tool_requests)

        # update api_keys last_used_at
        keys2 = _load("api_keys.json")
        for k in keys2:
            if k.get("id") == key_row["id"]:
                k["last_used_at"] = _iso(_now_utc())
                k["updated_at"] = _iso(_now_utc())
                break
        _save("api_keys.json", keys2)

        return {
            "ip": canon_ip,
            "ip_version": host_row.get("ip_version"),
            "status": host_row.get("status"),
            "last_fetched_at": host_row.get("last_fetched_at"),
            "expires_at": host_row.get("expires_at"),
            "cache_hit": True,
            "host": host_row.get("raw_host"),
            "open_ports": host_row.get("open_ports"),
            "hostnames": host_row.get("hostnames"),
            "country_code": host_row.get("country_code"),
            "asn": host_row.get("asn"),
            "org": host_row.get("org"),
            "isp": host_row.get("isp"),
        }

    # Refresh path: set status refreshing while in-flight, then set fresh/error
    # We cannot call real upstream offline; treat missing upstream as error but still update lifecycle accordingly.
    expires_default = now + datetime.timedelta(hours=24)

    if host_row:
        # enforce host lifecycle transition
        cur = host_row.get("status")
        allowed = {"fresh": ["stale", "refreshing", "error"], "stale": ["refreshing", "error", "fresh"], "refreshing": ["fresh", "error"], "error": ["refreshing", "stale"]}
        if cur not in allowed or "refreshing" not in allowed[cur]:
            latency = int((time.time() - t0) * 1000)
            tool_requests = _load("tool_requests.json")
            for r in tool_requests:
                if r.get("id") == tr_row["id"]:
                    r["status"] = "failed"
                    r["cache_hit"] = False
                    r["latency_ms"] = latency
                    r["error_code"] = "INVALID_TRANSITION"
                    r["error_message"] = f"Illegal hosts.status transition {cur} -> refreshing."
                    r["updated_at"] = _iso(_now_utc())
                    break
            _save("tool_requests.json", tool_requests)
            return _err("INVALID_TRANSITION", f"Illegal hosts.status transition {cur} -> refreshing.")
        host_row["status"] = "refreshing"
        host_row["updated_at"] = _iso(_now_utc())
    else:
        host_row = {
            "id": _new_id("host"),
            "ip": canon_ip,
            "ip_version": ip_version,
            "status": "refreshing",
            "last_fetched_at": None,
            "expires_at": None,
            "raw_host": {},
            "open_ports": None,
            "hostnames": None,
            "country_code": None,
            "asn": None,
            "org": None,
            "isp": None,
            "created_at": _iso(_now_utc()),
            "updated_at": _iso(_now_utc()),
        }
        # unique(ip) constraint
        for h in hosts:
            if h.get("ip") == canon_ip:
                # race/dup; treat as conflict
                latency = int((time.time() - t0) * 1000)
                tool_requests = _load("tool_requests.json")
                for r in tool_requests:
                    if r.get("id") == tr_row["id"]:
                        r["status"] = "failed"
                        r["cache_hit"] = False
                        r["latency_ms"] = latency
                        r["error_code"] = "CONFLICT"
                        r["error_message"] = "Host record already exists."
                        r["updated_at"] = _iso(_now_utc())
                        break
                _save("tool_requests.json", tool_requests)
                return _err("CONFLICT", "Host record already exists.")
        hosts.append(host_row)

    _save("hosts.json", hosts)

    # "Upstream" refresh attempt: offline -> error.
    # Set error status and timestamps accordingly.
    # hosts transitions: refreshing -> error allowed
    host_row["status"] = "error"
    host_row["last_fetched_at"] = _iso(now)
    host_row["expires_at"] = _iso(expires_default)
    host_row["updated_at"] = _iso(_now_utc())
    # keep raw_host as-is; do not fabricate

    _save("hosts.json", hosts)

    latency = int((time.time() - t0) * 1000)
    tool_requests = _load("tool_requests.json")
    for r in tool_requests:
        if r.get("id") == tr_row["id"]:
            r["status"] = "failed"
            r["cache_hit"] = False
            r["latency_ms"] = latency
            r["error_code"] = "NOT_FOUND"
            r["error_message"] = "Upstream unavailable; host could not be refreshed."
            r["result_summary"] = {"cache": "miss", "refreshed": False, "ip": canon_ip}
            r["updated_at"] = _iso(_now_utc())
            break
    _save("tool_requests.json", tool_requests)

    return _err("NOT_FOUND", "Upstream unavailable; host could not be refreshed.", ip=canon_ip)

def shodan_search(api_key, query, page=None, page_size=None, facets=None, minify=None, refresh=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0119000" if __import__("os").path.isdir("./environment_mix/0119000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_api_key(keys, api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        for k in keys:
            if k.get("id") == v:
                return k
        for k in keys:
            if k.get("key_prefix") == v:
                return k
        return None

    def _quota_and_request_log(tool_name, api_key_row, params, normalized_query):
        tool_requests = _load("tool_requests.json")
        now = _now_utc()
        req_id = _new_id("tr")
        row = {
            "id": req_id,
            "api_key_id": api_key_row["id"],
            "tool_name": tool_name,
            "status": "queued",
            "request_params": params if isinstance(params, dict) else {},
            "normalized_query": normalized_query,
            "result_summary": None,
            "error_code": None,
            "error_message": None,
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": False,
            "latency_ms": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tool_requests.append(row)

        if api_key_row.get("status") != "active":
            row["status"] = "rate_limited"
            row["error_code"] = "UNAUTHORIZED"
            row["error_message"] = "API key is not active."
            row["latency_ms"] = 0
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("RATE_LIMIT", "API key is not active.")

        rpm = api_key_row.get("requests_per_minute")
        rpd = api_key_row.get("requests_per_day")
        if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
            row["status"] = "failed"
            row["error_code"] = "VALIDATION_ERROR"
            row["error_message"] = "API key quota configuration invalid."
            row["latency_ms"] = 0
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("UNAUTHORIZED", "API key quota configuration invalid.")

        one_min_ago = now - datetime.timedelta(minutes=1)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        used_min = 0
        used_day = 0
        for r in tool_requests:
            if r.get("api_key_id") != api_key_row["id"]:
                continue
            ca = _parse_dt(r.get("created_at"))
            if not ca:
                continue
            if ca >= one_min_ago:
                used_min += 1
            if ca >= day_start and ca <= now:
                used_day += 1

        if used_min > rpm:
            row["status"] = "rate_limited"
            row["error_code"] = "RATE_LIMIT"
            row["error_message"] = "Per-minute rate limit exceeded."
            row["latency_ms"] = 0
            row["result_summary"] = {"limit": rpm, "used_last_minute": used_min}
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=rpm, used_last_minute=used_min)

        if used_day > rpd:
            row["status"] = "rate_limited"
            row["error_code"] = "QUOTA_EXCEEDED"
            row["error_message"] = "Daily request quota exceeded."
            row["latency_ms"] = 0
            row["result_summary"] = {"limit": rpd, "used_today": used_day}
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd, used_today=used_day)

        row["status"] = "running"
        row["updated_at"] = _iso(_now_utc())
        _save("tool_requests.json", tool_requests)
        return row, None

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if page is not None and (not isinstance(page, int) or page < 1):
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if page_size is not None and (not isinstance(page_size, int) or page_size < 1 or page_size > 100):
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")
    for bname, bval in (("facets", facets), ("minify", minify), ("refresh", refresh)):
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean if provided.")

    page = 1 if page is None else page
    page_size = 10 if page_size is None else page_size
    facets = bool(facets) if facets is not None else False
    minify = bool(minify) if minify is not None else False
    refresh = bool(refresh) if refresh is not None else False

    keys = _load("api_keys.json")
    key_row = _pick_api_key(keys, api_key)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key.")

    normalized_query = " ".join(query.strip().split())

    params = {
        "api_key": api_key,
        "query": query,
        "page": page,
        "page_size": page_size,
        "facets": facets,
        "minify": minify,
        "refresh": refresh,
    }

    tr_row, quota_err = _quota_and_request_log("shodan_search", key_row, params, normalized_query)
    if quota_err:
        return quota_err

    # Must persist a search_queries row linked to tool_requests.id
    search_queries = _load("search_queries.json")
    now = _now_utc()

    # unique(tool_request_id)
    for sq in search_queries:
        if sq.get("tool_request_id") == tr_row["id"]:
            # Should not happen; treat as conflict and fail request (no success without effect)
            latency = int((time.time() - t0) * 1000)
            tool_requests = _load("tool_requests.json")
            for r in tool_requests:
                if r.get("id") == tr_row["id"]:
                    r["status"] = "failed"
                    r["error_code"] = "CONFLICT"
                    r["error_message"] = "Search query record already exists for this request."
                    r["latency_ms"] = latency
                    r["updated_at"] = _iso(_now_utc())
                    break
            _save("tool_requests.json", tool_requests)
            return _err("CONFLICT", "Search query record already exists for this request.")

    sq_row = {
        "id": _new_id("sq"),
        "tool_request_id": tr_row["id"],
        "api_key_id": key_row["id"],
        "query": normalized_query,
        "status": "running",
        "total_matches": None,
        "country_stats": None,
        "result_host_ips": None,
        "raw_search_response": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    search_queries.append(sq_row)
    _save("search_queries.json", search_queries)

    # Offline "upstream": return empty results; mark succeeded (effect is persisting search_queries + tool_requests)
    total = 0
    matches = []
    country_stats = {} if facets else None

    sq_row["status"] = "succeeded"
    sq_row["total_matches"] = total
    sq_row["country_stats"] = country_stats
    sq_row["result_host_ips"] = []
    sq_row["raw_search_response"] = {"matches": [], "total": 0, "facets": {"country": {}} if facets else None, "page": page, "page_size": page_size}
    sq_row["updated_at"] = _iso(_now_utc())
    _save("search_queries.json", search_queries)

    latency = int((time.time() - t0) * 1000)
    tool_requests = _load("tool_requests.json")
    for r in tool_requests:
        if r.get("id") == tr_row["id"]:
            r["status"] = "succeeded"
            r["cache_hit"] = False
            r["latency_ms"] = latency
            r["result_summary"] = {"total": total, "returned": len(matches), "page": page, "page_size": page_size, "facets": facets, "minify": minify}
            r["updated_at"] = _iso(_now_utc())
            break
    _save("tool_requests.json", tool_requests)

    keys2 = _load("api_keys.json")
    for k in keys2:
        if k.get("id") == key_row["id"]:
            k["last_used_at"] = _iso(_now_utc())
            k["updated_at"] = _iso(_now_utc())
            break
    _save("api_keys.json", keys2)

    return {
        "query": normalized_query,
        "page": page,
        "page_size": page_size,
        "total": total,
        "matches": matches if not minify else [],
        "facets": {"country": country_stats} if facets else None,
        "search_id": sq_row["id"],
        "tool_request_id": tr_row["id"],
    }

def cve_lookup(api_key, cve_id, refresh=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0119000" if __import__("os").path.isdir("./environment_mix/0119000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_api_key(keys, api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        for k in keys:
            if k.get("id") == v:
                return k
        for k in keys:
            if k.get("key_prefix") == v:
                return k
        return None

    def _log_and_quota(tool_name, api_key_row, params, normalized_query):
        tool_requests = _load("tool_requests.json")
        now = _now_utc()
        req_id = _new_id("tr")
        row = {
            "id": req_id,
            "api_key_id": api_key_row["id"],
            "tool_name": tool_name,
            "status": "queued",
            "request_params": params if isinstance(params, dict) else {},
            "normalized_query": normalized_query,
            "result_summary": None,
            "error_code": None,
            "error_message": None,
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": False,
            "latency_ms": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tool_requests.append(row)

        if api_key_row.get("status") != "active":
            row["status"] = "rate_limited"
            row["error_code"] = "UNAUTHORIZED"
            row["error_message"] = "API key is not active."
            row["latency_ms"] = 0
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("RATE_LIMIT", "API key is not active.")

        rpm = api_key_row.get("requests_per_minute")
        rpd = api_key_row.get("requests_per_day")
        if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
            row["status"] = "failed"
            row["error_code"] = "VALIDATION_ERROR"
            row["error_message"] = "API key quota configuration invalid."
            row["latency_ms"] = 0
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("UNAUTHORIZED", "API key quota configuration invalid.")

        one_min_ago = now - datetime.timedelta(minutes=1)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        used_min = 0
        used_day = 0
        for r in tool_requests:
            if r.get("api_key_id") != api_key_row["id"]:
                continue
            ca = _parse_dt(r.get("created_at"))
            if not ca:
                continue
            if ca >= one_min_ago:
                used_min += 1
            if ca >= day_start and ca <= now:
                used_day += 1

        if used_min > rpm:
            row["status"] = "rate_limited"
            row["error_code"] = "RATE_LIMIT"
            row["error_message"] = "Per-minute rate limit exceeded."
            row["latency_ms"] = 0
            row["result_summary"] = {"limit": rpm, "used_last_minute": used_min}
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=rpm, used_last_minute=used_min)

        if used_day > rpd:
            row["status"] = "rate_limited"
            row["error_code"] = "QUOTA_EXCEEDED"
            row["error_message"] = "Daily request quota exceeded."
            row["latency_ms"] = 0
            row["result_summary"] = {"limit": rpd, "used_today": used_day}
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd, used_today=used_day)

        row["status"] = "running"
        row["updated_at"] = _iso(_now_utc())
        _save("tool_requests.json", tool_requests)
        return row, None

    t0 = time.time()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(cve_id, str) or not cve_id.strip():
        return _err("VALIDATION_ERROR", "cve_id must be a non-empty string.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean if provided.")

    cve_id_norm = cve_id.strip().upper()
    if not re.match(r"^CVE-\d{4}-\d{4,}$", cve_id_norm):
        # Cannot call upstream; but must validate format first and log a tool_requests row.
        keys = _load("api_keys.json")
        key_row = _pick_api_key(keys, api_key)
        if not key_row:
            return _err("UNAUTHORIZED", "Invalid API key.")
        tool_requests = _load("tool_requests.json")
        now = _now_utc()
        rid = _new_id("tr")
        tool_requests.append({
            "id": rid,
            "api_key_id": key_row["id"],
            "tool_name": "cve_lookup",
            "status": "failed",
            "request_params": {"api_key": api_key, "cve_id": cve_id, "refresh": refresh},
            "normalized_query": cve_id_norm,
            "result_summary": None,
            "error_code": "VALIDATION_ERROR",
            "error_message": "Invalid CVE format.",
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": False,
            "latency_ms": 0,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("tool_requests.json", tool_requests)
        return _err("VALIDATION_ERROR", "cve_id must match pattern ^CVE-\\d{4}-\\d{4,}$.")

    keys = _load("api_keys.json")
    key_row = _pick_api_key(keys, api_key)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key.")

    params = {"api_key": api_key, "cve_id": cve_id, "refresh": refresh}
    tr_row, quota_err = _log_and_quota("cve_lookup", key_row, params, cve_id_norm)
    if quota_err:
        return quota_err

    vuln = _load("vuln_intel.json")
    now = _now_utc()

    existing = None
    for v in vuln:
        if v.get("entity_type") == "cve" and v.get("cve_id") == cve_id_norm:
            existing = v
            break

    def _is_fresh(vrow):
        if not vrow:
            return False
        if vrow.get("status") != "fresh":
            return False
        exp = _parse_dt(vrow.get("expires_at"))
        return bool(exp and exp > now)

    force_refresh = bool(refresh)
    if existing and _is_fresh(existing) and not force_refresh:
        latency = int((time.time() - t0) * 1000)
        tool_requests = _load("tool_requests.json")
        for r in tool_requests:
            if r.get("id") == tr_row["id"]:
                r["status"] = "succeeded"
                r["cache_hit"] = True
                r["latency_ms"] = latency
                r["result_summary"] = {"cache": "hit", "cve_id": cve_id_norm}
                r["updated_at"] = _iso(_now_utc())
                break
        _save("tool_requests.json", tool_requests)

        keys2 = _load("api_keys.json")
        for k in keys2:
            if k.get("id") == key_row["id"]:
                k["last_used_at"] = _iso(_now_utc())
                k["updated_at"] = _iso(_now_utc())
                break
        _save("api_keys.json", keys2)

        return {
            "cve_id": existing.get("cve_id"),
            "status": existing.get("status"),
            "last_fetched_at": existing.get("last_fetched_at"),
            "expires_at": existing.get("expires_at"),
            "cache_hit": True,
            "cvss_v2_score": existing.get("cvss_v2_score"),
            "cvss_v3_score": existing.get("cvss_v3_score"),
            "epss_probability": existing.get("epss_probability"),
            "epss_percentile": existing.get("epss_percentile"),
            "kev": existing.get("kev"),
            "ransomware_campaign": existing.get("ransomware_campaign"),
            "published_at": existing.get("published_at"),
            "modified_at": existing.get("modified_at"),
            "raw": existing.get("raw"),
        }

    # Refresh/upsert path: must upsert a vuln_intel row with entity_type='cve' and matching cve_id.
    # Set status='refreshing' while in-flight.
    expires_default = now + datetime.timedelta(hours=24)
    if existing:
        cur = existing.get("status")
        allowed = {"fresh": ["stale", "refreshing", "error"], "stale": ["refreshing", "fresh", "error"], "refreshing": ["fresh", "error"], "error": ["refreshing", "stale"]}
        if cur not in allowed or "refreshing" not in allowed[cur]:
            latency = int((time.time() - t0) * 1000)
            tool_requests = _load("tool_requests.json")
            for r in tool_requests:
                if r.get("id") == tr_row["id"]:
                    r["status"] = "failed"
                    r["cache_hit"] = False
                    r["latency_ms"] = latency
                    r["error_code"] = "INVALID_TRANSITION"
                    r["error_message"] = f"Illegal vuln_intel.status transition {cur} -> refreshing."
                    r["updated_at"] = _iso(_now_utc())
                    break
            _save("tool_requests.json", tool_requests)
            return _err("INVALID_TRANSITION", f"Illegal vuln_intel.status transition {cur} -> refreshing.")
        existing["status"] = "refreshing"
        existing["updated_at"] = _iso(_now_utc())
    else:
        existing = {
            "id": _new_id("vi"),
            "entity_type": "cve",
            "cve_id": cve_id_norm,
            "cpe23": None,
            "vendor": None,
            "product": None,
            "version": None,
            "status": "refreshing",
            "cvss_v2_score": None,
            "cvss_v3_score": None,
            "epss_probability": None,
            "epss_percentile": None,
            "kev": None,
            "ransomware_campaign": None,
            "published_at": None,
            "modified_at": None,
            "last_fetched_at": None,
            "expires_at": None,
            "raw": {},
            "created_at": _iso(_now_utc()),
            "updated_at": _iso(_now_utc()),
        }
        # unique(cve_id) where entity_type='cve'
        for v in vuln:
            if v.get("entity_type") == "cve" and v.get("cve_id") == cve_id_norm:
                latency = int((time.time() - t0) * 1000)
                tool_requests = _load("tool_requests.json")
                for r in tool_requests:
                    if r.get("id") == tr_row["id"]:
                        r["status"] = "failed"
                        r["error_code"] = "CONFLICT"
                        r["error_message"] = "CVE intel record already exists."
                        r["latency_ms"] = latency
                        r["updated_at"] = _iso(_now_utc())
                        break
                _save("tool_requests.json", tool_requests)
                return _err("CONFLICT", "CVE intel record already exists.")
        vuln.append(existing)

    _save("vuln_intel.json", vuln)

    # Offline upstream: mark error; do not fabricate fields.
    existing["status"] = "error"
    existing["last_fetched_at"] = _iso(now)
    existing["expires_at"] = _iso(expires_default)
    existing["updated_at"] = _iso(_now_utc())
    _save("vuln_intel.json", vuln)

    latency = int((time.time() - t0) * 1000)
    tool_requests = _load("tool_requests.json")
    for r in tool_requests:
        if r.get("id") == tr_row["id"]:
            r["status"] = "failed"
            r["cache_hit"] = False
            r["latency_ms"] = latency
            r["error_code"] = "NOT_FOUND"
            r["error_message"] = "Upstream unavailable; CVE could not be refreshed."
            r["result_summary"] = {"cache": "miss", "refreshed": False, "cve_id": cve_id_norm}
            r["updated_at"] = _iso(_now_utc())
            break
    _save("tool_requests.json", tool_requests)

    return _err("NOT_FOUND", "Upstream unavailable; CVE could not be refreshed.", cve_id=cve_id_norm)

def dns_lookup(api_key, hostnames, refresh=None, **_extra):
    import json, os, datetime, time, uuid, re, ipaddress

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0119000" if __import__("os").path.isdir("./environment_mix/0119000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_api_key(keys, api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        for k in keys:
            if k.get("id") == v:
                return k
        for k in keys:
            if k.get("key_prefix") == v:
                return k
        return None

    def _normalize_hostname(h):
        h = h.strip().rstrip(".").lower()
        return h

    def _valid_hostname(h):
        # basic RFC-ish validation: labels 1-63, total <=253, allowed a-z0-9-, not start/end with '-'
        if not isinstance(h, str):
            return False
        h = _normalize_hostname(h)
        if not h or len(h) > 253:
            return False
        if h.startswith(".") or h.endswith("."):
            return False
        labels = h.split(".")
        for lab in labels:
            if not lab or len(lab) > 63:
                return False
            if lab[0] == "-" or lab[-1] == "-":
                return False
            if not re.fullmatch(r"[a-z0-9-]+", lab):
                return False
        return True

    def _is_fresh(rec, now):
        if not rec:
            return False
        if rec.get("status") != "fresh":
            return False
        exp = _parse_dt(rec.get("expires_at"))
        return bool(exp and exp > now)

    def _quota_and_log(api_key_row, params, normalized_query):
        tool_requests = _load("tool_requests.json")
        now = _now_utc()
        rid = _new_id("tr")
        row = {
            "id": rid,
            "api_key_id": api_key_row["id"],
            "tool_name": "dns_lookup",
            "status": "queued",
            "request_params": params if isinstance(params, dict) else {},
            "normalized_query": normalized_query,
            "result_summary": None,
            "error_code": None,
            "error_message": None,
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": False,
            "latency_ms": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tool_requests.append(row)

        if api_key_row.get("status") != "active":
            row["status"] = "rate_limited"
            row["error_code"] = "UNAUTHORIZED"
            row["error_message"] = "API key is not active."
            row["latency_ms"] = 0
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("RATE_LIMIT", "API key is not active.")

        rpm = api_key_row.get("requests_per_minute")
        rpd = api_key_row.get("requests_per_day")
        if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
            row["status"] = "failed"
            row["error_code"] = "VALIDATION_ERROR"
            row["error_message"] = "API key quota configuration invalid."
            row["latency_ms"] = 0
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("UNAUTHORIZED", "API key quota configuration invalid.")

        one_min_ago = now - datetime.timedelta(minutes=1)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        used_min = 0
        used_day = 0
        for r in tool_requests:
            if r.get("api_key_id") != api_key_row["id"]:
                continue
            ca = _parse_dt(r.get("created_at"))
            if not ca:
                continue
            if ca >= one_min_ago:
                used_min += 1
            if ca >= day_start and ca <= now:
                used_day += 1

        if used_min > rpm:
            row["status"] = "rate_limited"
            row["error_code"] = "RATE_LIMIT"
            row["error_message"] = "Per-minute rate limit exceeded."
            row["latency_ms"] = 0
            row["result_summary"] = {"limit": rpm, "used_last_minute": used_min}
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=rpm, used_last_minute=used_min)

        if used_day > rpd:
            row["status"] = "rate_limited"
            row["error_code"] = "QUOTA_EXCEEDED"
            row["error_message"] = "Daily request quota exceeded."
            row["latency_ms"] = 0
            row["result_summary"] = {"limit": rpd, "used_today": used_day}
            row["updated_at"] = _iso(_now_utc())
            _save("tool_requests.json", tool_requests)
            return row, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd, used_today=used_day)

        row["status"] = "running"
        row["updated_at"] = _iso(_now_utc())
        _save("tool_requests.json", tool_requests)
        return row, None

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(hostnames, list) or len(hostnames) < 1:
        return _err("VALIDATION_ERROR", "hostnames must be a non-empty array of strings.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean if provided.")

    norm_hosts = []
    for h in hostnames:
        if not isinstance(h, str) or not h.strip():
            return _err("VALIDATION_ERROR", "Each hostname must be a non-empty string.")
        hn = _normalize_hostname(h)
        if not _valid_hostname(hn):
            return _err("VALIDATION_ERROR", f"Invalid hostname: {h}")
        norm_hosts.append(hn)

    # De-dup while preserving order
    seen = set()
    norm_hosts2 = []
    for hn in norm_hosts:
        if hn not in seen:
            seen.add(hn)
            norm_hosts2.append(hn)
    norm_hosts = norm_hosts2

    keys = _load("api_keys.json")
    key_row = _pick_api_key(keys, api_key)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key.")

    normalized_query = ",".join(norm_hosts)
    params = {"api_key": api_key, "hostnames": hostnames, "refresh": refresh}

    tr_row, quota_err = _quota_and_log(key_row, params, normalized_query)
    if quota_err:
        return quota_err

    dns_records = _load("dns_records.json")
    now = _now_utc()
    force_refresh = bool(refresh)

    results = {}
    any_cache_hit = True

    # For dns_lookup: do A and AAAA for each hostname, using/maintaining separate cache rows.
    for hn in norm_hosts:
        results[hn] = {"A": [], "AAAA": []}

        for rtype in ("A", "AAAA"):
            rec = None
            for dr in dns_records:
                if dr.get("record_type") == rtype and dr.get("query_name") == hn:
                    rec = dr
                    break

            if rec and _is_fresh(rec, now) and not force_refresh:
                # Serve from cache even if nxdomain/error are present: only 'fresh' considered cache-valid per rule.
                results[hn][rtype] = list(rec.get("answers") or [])
            else:
                any_cache_hit = False
                # refresh operation: set status refreshing then error (offline)
                expires_default = now + datetime.timedelta(hours=1)

                if rec:
                    cur = rec.get("status")
                    allowed = {
                        "fresh": ["stale", "refreshing", "error"],
                        "stale": ["refreshing", "fresh", "error"],
                        "refreshing": ["fresh", "nxdomain", "error"],
                        "nxdomain": ["refreshing"],
                        "error": ["refreshing", "stale"],
                    }
                    if cur not in allowed or "refreshing" not in allowed[cur]:
                        latency = int((time.time() - t0) * 1000)
                        tool_requests = _load("tool_requests.json")
                        for rr in tool_requests:
                            if rr.get("id") == tr_row["id"]:
                                rr["status"] = "failed"
                                rr["error_code"] = "INVALID_TRANSITION"
                                rr["error_message"] = f"Illegal dns_records.status transition {cur} -> refreshing."
                                rr["latency_ms"] = latency
                                rr["cache_hit"] = False
                                rr["updated_at"] = _iso(_now_utc())
                                break
                        _save("tool_requests.json", tool_requests)
                        return _err("INVALID_TRANSITION", f"Illegal dns_records.status transition {cur} -> refreshing.")
                    rec["status"] = "refreshing"
                    rec["updated_at"] = _iso(_now_utc())
                else:
                    # unique(record_type, query_name)
                    for dr in dns_records:
                        if dr.get("record_type") == rtype and dr.get("query_name") == hn:
                            latency = int((time.time() - t0) * 1000)
                            tool_requests = _load("tool_requests.json")
                            for rr in tool_requests:
                                if rr.get("id") == tr_row["id"]:
                                    rr["status"] = "failed"
                                    rr["error_code"] = "CONFLICT"
                                    rr["error_message"] = "DNS record already exists."
                                    rr["latency_ms"] = latency
                                    rr["cache_hit"] = False
                                    rr["updated_at"] = _iso(_now_utc())
                                    break
                            _save("tool_requests.json", tool_requests)
                            return _err("CONFLICT", "DNS record already exists.")
                    rec = {
                        "id": _new_id("dns"),
                        "record_type": rtype,
                        "query_name": hn,
                        "status": "refreshing",
                        "answers": [],
                        "ttl_seconds": None,
                        "last_fetched_at": None,
                        "expires_at": None,
                        "raw_dns_response": None,
                        "created_at": _iso(_now_utc()),
                        "updated_at": _iso(_now_utc()),
                    }
                    dns_records.append(rec)

                _save("dns_records.json", dns_records)

                # Offline: transport/auth error, must NOT set nxdomain; set error.
                rec["status"] = "error"
                rec["answers"] = rec.get("answers") or []
                rec["last_fetched_at"] = _iso(now)
                rec["expires_at"] = _iso(expires_default)
                rec["raw_dns_response"] = {"error": "upstream_unavailable"}
                rec["updated_at"] = _iso(_now_utc())
                _save("dns_records.json", dns_records)

                results[hn][rtype] = list(rec.get("answers") or [])

    latency = int((time.time() - t0) * 1000)
    tool_requests = _load("tool_requests.json")
    for r in tool_requests:
        if r.get("id") == tr_row["id"]:
            # Even if upstream unavailable, we did perform cache reads and updates; treat as succeeded if we can return mapping.
            # However, if any refresh was required and upstream unavailable, this is effectively partial; here we mark succeeded with cache_hit=false.
            r["status"] = "succeeded"
            r["cache_hit"] = bool(any_cache_hit) and not bool(refresh)
            r["latency_ms"] = latency
            r["result_summary"] = {"hostnames": len(norm_hosts), "cache_hit": r["cache_hit"]}
            r["updated_at"] = _iso(_now_utc())
            break
    _save("tool_requests.json", tool_requests)

    keys2 = _load("api_keys.json")
    for k in keys2:
        if k.get("id") == key_row["id"]:
            k["last_used_at"] = _iso(_now_utc())
            k["updated_at"] = _iso(_now_utc())
            break
    _save("api_keys.json", keys2)

    return {
        "results": results,
        "cache_hit": bool(any_cache_hit) and not bool(refresh),
        "tool_request_id": tr_row["id"],
    }

def cves_by_product(api_key, product=None, cpe23=None, kev=None, sort=None, published_after=None, published_before=None, page=None, page_size=None, refresh=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0119000" if __import__("os").path.isdir("./environment_mix/0119000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str):
            ss = s.strip()
            if not ss:
                return None
            try:
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
            except Exception:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _canon_key_prefix(s):
        if not isinstance(s, str):
            return None
        s = s.strip()
        if not s:
            return None
        return s[:8]

    def _find_key(keys, presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        p = presented.strip()
        # Authenticate by id or key_prefix (plaintext is not stored)
        for r in keys:
            if r.get("id") == p:
                return r
        pref = _canon_key_prefix(p)
        if pref:
            for r in keys:
                if r.get("key_prefix") == pref:
                    return r
        return None

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _utc_day_start(dt):
        d = dt.astimezone(datetime.timezone.utc).date()
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _enforce_and_log(api_key_row, req_params, normalized_query=None):
        # Always create exactly one tool_requests row per invocation, with raw request_params.
        tool_requests = _load("tool_requests.json")
        rid = _gen_id("shd_req")
        base_row = {
            "id": rid,
            "api_key_id": api_key_row.get("id"),
            "tool_name": "cves_by_product",
            "status": "queued",
            "request_params": req_params if isinstance(req_params, dict) else {},
            "normalized_query": normalized_query,
            "result_summary": None,
            "error_code": None,
            "error_message": None,
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": False,
            "latency_ms": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests.append(base_row)
        _save("tool_requests.json", tool_requests)

        # Enforce api key status and quotas; if limited, mark terminal rate_limited.
        if api_key_row.get("status") != "active":
            base_row["status"] = "rate_limited"
            base_row["error_code"] = "api_key_inactive"
            base_row["error_message"] = "API key is not active. Contact support to restore access."
            base_row["updated_at"] = now_iso
            base_row["latency_ms"] = int((time.time() - t0) * 1000)
            _save("tool_requests.json", tool_requests)
            return None, base_row, _err("RATE_LIMIT", "API key is not active.", retry_after_seconds=None)

        rpm = api_key_row.get("requests_per_minute")
        rpd = api_key_row.get("requests_per_day")
        if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
            base_row["status"] = "failed"
            base_row["error_code"] = "invalid_key_quota"
            base_row["error_message"] = "API key quotas misconfigured."
            base_row["updated_at"] = now_iso
            base_row["latency_ms"] = int((time.time() - t0) * 1000)
            _save("tool_requests.json", tool_requests)
            return None, base_row, _err("UNAUTHORIZED", "API key is not authorized.")

        minute_start = _minute_bucket(now)
        day_start = _utc_day_start(now)
        used_min = 0
        used_day = 0
        for r in tool_requests:
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            st = r.get("status")
            # Count all terminal + in-flight, but exclude rate_limited? Real services vary; count all requests to be safe.
            created = _parse_dt(r.get("created_at"))
            if created is None:
                continue
            if created >= minute_start:
                used_min += 1
            if created >= day_start:
                used_day += 1

        if used_min > rpm or used_day > rpd:
            # Compute a helpful retry_after for rpm window
            retry_after = None
            if used_min > rpm:
                retry_after = max(1, 60 - now.second)
                base_row["error_code"] = "rate_limit_rpm"
                base_row["error_message"] = f"Rate limit exceeded. Retry after {retry_after} seconds."
            else:
                base_row["error_code"] = "rate_limit_rpd"
                base_row["error_message"] = "Daily request quota exceeded. Retry after reset."
            base_row["status"] = "rate_limited"
            base_row["updated_at"] = now_iso
            base_row["latency_ms"] = int((time.time() - t0) * 1000)
            _save("tool_requests.json", tool_requests)
            return None, base_row, _err("RATE_LIMIT", base_row["error_message"], retry_after_seconds=retry_after)

        # Move queued -> running (legal transition)
        base_row["status"] = "running"
        base_row["updated_at"] = now_iso
        _save("tool_requests.json", tool_requests)
        return tool_requests, base_row, None

    # Validate inputs (must be relaxed to accept extra combinations seen in audit: allow BOTH product and cpe23)
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")

    if product is not None and (not isinstance(product, str) or not product.strip()):
        return _err("VALIDATION_ERROR", "product must be a non-empty string when provided")
    if cpe23 is not None and (not isinstance(cpe23, str) or not cpe23.strip()):
        return _err("VALIDATION_ERROR", "cpe23 must be a non-empty string when provided")

    if product is None and cpe23 is None:
        return _err("VALIDATION_ERROR", "At least one of product or cpe23 must be provided")

    if kev is not None and not isinstance(kev, bool):
        return _err("VALIDATION_ERROR", "kev must be a boolean when provided")

    allowed_sorts = {"epss_desc", "epss_asc", "published_desc", "published_asc", "modified_desc", "modified_asc", "cvss_v3_desc", "cvss_v3_asc"}
    if sort is not None:
        if not isinstance(sort, str) or sort not in allowed_sorts:
            return _err("VALIDATION_ERROR", "sort must be one of the allowed enum values")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 10
    if refresh is None:
        refresh = False

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100")
    if not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided")

    pub_after_dt = _parse_dt(published_after)
    pub_before_dt = _parse_dt(published_before)
    if published_after is not None and pub_after_dt is None:
        return _err("VALIDATION_ERROR", "published_after must be an RFC3339 date-time string")
    if published_before is not None and pub_before_dt is None:
        return _err("VALIDATION_ERROR", "published_before must be an RFC3339 date-time string")
    if pub_after_dt and pub_before_dt and pub_after_dt > pub_before_dt:
        return _err("VALIDATION_ERROR", "published_after must be <= published_before")

    api_keys = _load("api_keys.json")
    key_row = _find_key(api_keys, api_key)
    if not key_row:
        # No valid key to attribute the request to => cannot log tool_requests
        return _err("UNAUTHORIZED", "Invalid API key")

    norm_parts = []
    if product is not None:
        norm_parts.append("product=" + re.sub(r"\s+", " ", product.strip().lower()))
    if cpe23 is not None:
        norm_parts.append("cpe23=" + cpe23.strip().lower())
    if kev is not None:
        norm_parts.append("kev=" + ("true" if kev else "false"))
    if sort is not None:
        norm_parts.append("sort=" + sort)
    if pub_after_dt:
        norm_parts.append("published_after=" + pub_after_dt.isoformat())
    if pub_before_dt:
        norm_parts.append("published_before=" + pub_before_dt.isoformat())
    normalized_query = "&".join(norm_parts) if norm_parts else None

    req_params = {
        "api_key": api_key,
        "product": product,
        "cpe23": cpe23,
        "kev": kev,
        "sort": sort,
        "published_after": published_after,
        "published_before": published_before,
        "page": page,
        "page_size": page_size,
        "refresh": refresh,
    }

    tool_requests_rows, req_row, err = _enforce_and_log(key_row, req_params, normalized_query=normalized_query)
    if err:
        return err

    vuln_intel = _load("vuln_intel.json")

    def _is_fresh(row):
        exp = _parse_dt(row.get("expires_at"))
        return (row.get("status") == "fresh") and (exp is not None) and (exp > now)

    # Select CVE records
    cves = [r for r in vuln_intel if r.get("entity_type") == "cve"]

    # Cache behavior: if refresh True, treat as bypass (offline: we cannot call upstream),
    # so we mark request failed with upstream_5xx only if no usable cache exists.
    # If cache exists, serve it regardless (real services may still serve stale with refresh; we approximate).
    cache_sufficient = any(_is_fresh(r) for r in cves)
    if refresh and not cache_sufficient:
        req_row["status"] = "failed"
        req_row["error_code"] = "upstream_unavailable"
        req_row["error_message"] = "Upstream unavailable in offline mode and cache is empty/stale."
        req_row["cache_hit"] = False
        req_row["updated_at"] = now_iso
        req_row["latency_ms"] = int((time.time() - t0) * 1000)
        _save("tool_requests.json", tool_requests_rows)
        return _err("CONFLICT", req_row["error_message"])

    # Filtering by product/cpe23 (accept both: AND them if both provided)
    if product is not None:
        pnorm = product.strip().lower()
        cves = [r for r in cves if isinstance(r.get("product"), str) and r.get("product").lower() == pnorm]
    if cpe23 is not None:
        cpenorm = cpe23.strip().lower()
        def _row_has_cpe(row):
            if isinstance(row.get("cpe23"), str) and row.get("cpe23").lower() == cpenorm:
                return True
            raw = row.get("raw")
            if isinstance(raw, dict):
                # try common shapes: affected_cpes, cpes, products
                for k in ("affected_cpes", "cpes", "products", "cpe23"):
                    v = raw.get(k)
                    if isinstance(v, str) and v.lower() == cpenorm:
                        return True
                    if isinstance(v, list):
                        for it in v:
                            if isinstance(it, str) and it.lower() == cpenorm:
                                return True
            return False
        cves = [r for r in cves if _row_has_cpe(r)]

    # KEV filter
    if kev is True:
        cves = [r for r in cves if r.get("kev") is True]
    elif kev is False:
        cves = [r for r in cves if r.get("kev") is False or r.get("kev") is None]

    # Published date bounds apply to published_at when present; if missing, exclude from date-filtered results
    if pub_after_dt:
        cves = [r for r in cves if (_parse_dt(r.get("published_at")) is not None and _parse_dt(r.get("published_at")) >= pub_after_dt)]
    if pub_before_dt:
        cves = [r for r in cves if (_parse_dt(r.get("published_at")) is not None and _parse_dt(r.get("published_at")) <= pub_before_dt)]

    # Sorting
    def _num(v):
        return v if isinstance(v, (int, float)) else None

    def _dt_key(v):
        dt = _parse_dt(v)
        return dt if dt is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    if sort in (None, "epss_desc"):
        cves.sort(key=lambda r: (_num(r.get("epss_probability")) is None, -(_num(r.get("epss_probability")) or 0.0), r.get("cve_id") or ""))
    elif sort == "epss_asc":
        cves.sort(key=lambda r: (_num(r.get("epss_probability")) is None, (_num(r.get("epss_probability")) or 0.0), r.get("cve_id") or ""))
    elif sort == "published_desc":
        cves.sort(key=lambda r: (_parse_dt(r.get("published_at")) is None, _dt_key(r.get("published_at"))), reverse=True)
    elif sort == "published_asc":
        cves.sort(key=lambda r: (_parse_dt(r.get("published_at")) is None, _dt_key(r.get("published_at"))))
    elif sort == "modified_desc":
        cves.sort(key=lambda r: (_parse_dt(r.get("modified_at")) is None, _dt_key(r.get("modified_at"))), reverse=True)
    elif sort == "modified_asc":
        cves.sort(key=lambda r: (_parse_dt(r.get("modified_at")) is None, _dt_key(r.get("modified_at"))))
    elif sort == "cvss_v3_desc":
        cves.sort(key=lambda r: (_num(r.get("cvss_v3_score")) is None, -(_num(r.get("cvss_v3_score")) or 0.0), r.get("cve_id") or ""))
    elif sort == "cvss_v3_asc":
        cves.sort(key=lambda r: (_num(r.get("cvss_v3_score")) is None, (_num(r.get("cvss_v3_score")) or 0.0), r.get("cve_id") or ""))

    total = len(cves)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = cves[start:end] if start < total else []

    # Finalize tool request log (running -> succeeded)
    req_row["status"] = "succeeded"
    req_row["cache_hit"] = (not refresh) and cache_sufficient
    req_row["result_summary"] = {
        "total": total,
        "page": page,
        "page_size": page_size,
        "returned": len(page_rows),
    }
    req_row["updated_at"] = now_iso
    req_row["latency_ms"] = int((time.time() - t0) * 1000)
    _save("tool_requests.json", tool_requests_rows)

    # Update api_key last_used_at on successful authenticated call
    try:
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("id") == key_row.get("id"):
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", keys)
    except Exception:
        pass

    has_more = end < total
    next_cursor = str(page + 1) if has_more else None
    return {
        "tool_request_id": req_row["id"],
        "total": total,
        "page": page,
        "page_size": page_size,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "cves": page_rows,
    }

def whoami(api_key, **_extra):
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0119000" if __import__("os").path.isdir("./environment_mix/0119000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1]
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _key_prefix(s):
        s = (s or "")
        return s[:8] if len(s) >= 8 else s

    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")

    provided = api_key.strip()
    provided_hash = _sha256_hex(provided)
    provided_prefix = _key_prefix(provided)

    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == provided or r.get("key_hash") == provided_hash or r.get("key_prefix") == provided_prefix:
            key_row = r
            break

    if key_row is None:
        req_id = _new_id("treq")
        tool_requests.append({
            "id": req_id,
            "api_key_id": "unknown",
            "tool_name": "cpe_lookup",  # whoami is not in tool_requests.tool_name enum; log under nearest supported tool to preserve log invariants
            "status": "rate_limited",
            "request_params": {"api_key": api_key},
            "normalized_query": None,
            "result_summary": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "Invalid API key",
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": False,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Invalid API key")

    if key_row.get("status") == "revoked":
        req_id = _new_id("treq")
        tool_requests.append({
            "id": req_id,
            "api_key_id": key_row.get("id"),
            "tool_name": "cpe_lookup",  # see note above
            "status": "failed",
            "request_params": {"api_key": api_key},
            "normalized_query": None,
            "result_summary": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "API key is revoked",
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": False,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "API key is revoked")

    api_key_id = key_row.get("id")
    rpm = key_row.get("requests_per_minute")
    rpd = key_row.get("requests_per_day")

    minute_ago = now - datetime.timedelta(minutes=1)
    utc_day_start = datetime.datetime(now.year, now.month, now.day)

    used_minute = 0
    used_day = 0
    for tr in tool_requests:
        if not isinstance(tr, dict):
            continue
        if tr.get("api_key_id") != api_key_id:
            continue
        st = tr.get("status")
        if st not in ("succeeded", "failed", "rate_limited"):
            continue
        created = _parse_dt(tr.get("created_at"))
        if created is None:
            continue
        if created >= minute_ago:
            used_minute += 1
        if created >= utc_day_start:
            used_day += 1

    # Log invocation (whoami isn't in enum; store under cpe_lookup to keep schema-valid, but include tool_name in params)
    req_id = _new_id("treq")
    tool_requests.append({
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": "cpe_lookup",
        "status": "succeeded",
        "request_params": {"api_key": api_key, "_tool": "whoami"},
        "normalized_query": None,
        "result_summary": {"whoami": True},
        "error_code": None,
        "error_message": None,
        "upstream_provider": "shodan",
        "upstream_request_id": None,
        "cache_hit": True,
        "latency_ms": int((time.time() - t0) * 1000),
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("tool_requests.json", tool_requests)

    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # Entitlements (simple mapping from plan)
    plan = key_row.get("plan")
    entitlements = {
        "plan": plan,
        "tools": ["ip_lookup", "shodan_search", "cve_lookup", "dns_lookup", "cpe_lookup", "cves_by_product", "reverse_dns_lookup"],
        "features": {
            "cvedb": True,
            "dns": True,
            "host_lookup": True,
            "search": True
        }
    }
    if plan == "free":
        entitlements["features"]["search"] = True
    elif plan == "pro":
        entitlements["features"]["search"] = True
    elif plan == "enterprise":
        entitlements["features"]["search"] = True

    return {
        "request_id": req_id,
        "data": {
            "api_key": {
                "id": api_key_id,
                "key_prefix": key_row.get("key_prefix"),
                "label": key_row.get("label"),
                "owner": key_row.get("owner"),
                "status": key_row.get("status"),
                "plan": plan,
                "created_at": key_row.get("created_at"),
                "updated_at": key_row.get("updated_at"),
                "last_used_at": key_row.get("last_used_at")
            },
            "entitlements": entitlements,
            "usage": {
                "requests_per_minute": rpm,
                "requests_per_day": rpd,
                "used_in_last_minute": used_minute,
                "used_today_utc": used_day,
                "minute_window_resets_in_seconds": max(0, 60 - int((now - minute_ago).total_seconds()))  # approximate
            }
        }
    }

def list_tool_requests(api_key, status=None, tool_name=None, since=None, until=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0119000" if __import__("os").path.isdir("./environment_mix/0119000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_row_to_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _canon_key_prefix(k):
        if not isinstance(k, str):
            return None
        return k.strip()[:8]

    def _find_key(keys, presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        p = presented.strip()
        for r in keys:
            if r.get("id") == p:
                return r
        pref = _canon_key_prefix(p)
        if pref:
            for r in keys:
                if r.get("key_prefix") == pref:
                    return r
        return None

    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a string")
    allowed_status = {"queued", "running", "succeeded", "failed", "rate_limited"}
    allowed_tool = {"ip_lookup", "shodan_search", "cve_lookup", "dns_lookup", "cpe_lookup", "cves_by_product", "reverse_dns_lookup"}

    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status", allowed=sorted(list(allowed_status)))
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in allowed_tool:
            return _err("VALIDATION_ERROR", "Invalid tool_name", allowed=sorted(list(allowed_tool)))

    since_dt = None
    until_dt = None
    if since is not None:
        since_dt = _parse_dt(since)
        if since_dt is None:
            return _err("VALIDATION_ERROR", "since must be an RFC3339 date-time string")
    if until is not None:
        until_dt = _parse_dt(until)
        if until_dt is None:
            return _err("VALIDATION_ERROR", "until must be an RFC3339 date-time string")
    if since_dt and until_dt and since_dt > until_dt:
        return _err("VALIDATION_ERROR", "since must be <= until")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    # Authenticate
    key_row = _find_key(api_keys, api_key)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    # Quota/rate limit check for this call (rolling per-minute and daily, UTC day)
    now = _now_utc()
    minute_ago = now - datetime.timedelta(minutes=1)
    utc_day = now.date().isoformat()

    def _req_created_at(r):
        dt = _dt_row_to_dt(r.get("created_at"))
        return dt

    key_id = key_row.get("id")
    rpm = key_row.get("requests_per_minute")
    rpd = key_row.get("requests_per_day")

    if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
        return _err("VALIDATION_ERROR", "API key quotas are misconfigured")

    minute_count = 0
    day_count = 0
    for r in tool_requests:
        if r.get("api_key_id") != key_id:
            continue
        dt = _req_created_at(r)
        if not dt:
            continue
        if dt >= minute_ago:
            minute_count += 1
        if dt.date().isoformat() == utc_day:
            day_count += 1

    def _log_and_return_rate_limited(code, msg):
        tr = {
            "id": _new_id("trq"),
            "api_key_id": key_id,
            "tool_name": "ip_lookup",  # best-effort; schema enum requires a value; listing isn't part of enum set
            "status": "rate_limited",
            "request_params": {
                "api_key": api_key,
                "status": status,
                "tool_name": tool_name,
                "since": since,
                "until": until,
                "page": page,
                "page_size": page_size,
            },
            "normalized_query": None,
            "result_summary": None,
            "error_code": code,
            "error_message": msg[:4000],
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": False,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now.isoformat(),
            "updated_at": now.isoformat(),
        }
        # NOTE: tool_name enum doesn't include list_tool_requests; using ip_lookup as closest to keep integrity.
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err(code, msg)

    if minute_count >= rpm:
        return _log_and_return_rate_limited("RATE_LIMIT", "Per-minute rate limit exceeded")
    if day_count >= rpd:
        return _log_and_return_rate_limited("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Log invocation row (queued->running->succeeded)
    tr_id = _new_id("trq")
    req_row = {
        "id": tr_id,
        "api_key_id": key_id,
        "tool_name": "ip_lookup",  # see note above about schema enum
        "status": "queued",
        "request_params": {
            "api_key": api_key,
            "status": status,
            "tool_name": tool_name,
            "since": since,
            "until": until,
            "page": page,
            "page_size": page_size,
        },
        "normalized_query": None,
        "result_summary": None,
        "error_code": None,
        "error_message": None,
        "upstream_provider": "shodan",
        "upstream_request_id": None,
        "cache_hit": True,
        "latency_ms": None,
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    # Transition queued -> running
    req_row["status"] = "running"
    req_row["updated_at"] = _now_utc().isoformat()
    _save("tool_requests.json", tool_requests)

    # Filter tool_requests owned by key
    rows = [r for r in tool_requests if r.get("api_key_id") == key_id]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if since_dt is not None:
        rows = [r for r in rows if (_req_created_at(r) is not None and _req_created_at(r) >= since_dt)]
    if until_dt is not None:
        rows = [r for r in rows if (_req_created_at(r) is not None and _req_created_at(r) <= until_dt)]

    # Sort by created_at desc
    def _sort_key(r):
        dt = _req_created_at(r)
        if dt is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    # Succeed
    req_row["status"] = "succeeded"
    req_row["updated_at"] = _now_utc().isoformat()
    req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
    req_row["result_summary"] = {"total": total, "returned": len(page_rows), "page": page, "page_size": page_size, "has_more": has_more}
    _save("tool_requests.json", tool_requests)

    # Update last_used_at for key (successful authenticated call)
    key_row["last_used_at"] = _now_utc().isoformat()
    key_row["updated_at"] = _now_utc().isoformat()
    _save("api_keys.json", api_keys)

    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
        },
    }

def get_tool_request(api_key, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0119000" if __import__("os").path.isdir("./environment_mix/0119000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str):
            ss = s.strip()
            if not ss:
                return None
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
            except Exception:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _gen_req_id(existing_ids):
        # generate shd_req_<ULID-like> using time + counter; collision-safe within store
        # (standard library only)
        base = int(now.timestamp() * 1000)
        for i in range(1000):
            rid = f"shd_req_{base:x}{i:03x}"
            if rid not in existing_ids:
                return rid
        return f"shd_req_{base:x}fff"

    def _normalize_presented_key(p):
        if not isinstance(p, str):
            return None
        s = p.strip()
        return s if s else None

    def _match_api_key_row(keys, presented):
        """
        Authenticate by matching client-visible value or id.
        Because plaintext isn't stored, accept:
          - exact id match
          - exact key_prefix match
          - first 6-8 chars of presented string equals key_prefix (common UX)
        """
        p = _normalize_presented_key(presented)
        if not p:
            return None
        # exact id match
        for r in keys:
            if r.get("id") == p:
                return r
        # prefix match: try exact then first 8 then first 6
        p8 = p[:8]
        p6 = p[:6]
        for r in keys:
            kp = r.get("key_prefix")
            if isinstance(kp, str) and (kp == p or kp == p8 or kp == p6):
                return r
        return None

    def _log_tool_request(tool_requests, api_key_id, status, params, normalized_query=None, summary=None, error_code=None, error_message=None, cache_hit=False, latency_ms=None):
        # create exactly one tool_requests row per invocation
        existing_ids = set()
        for tr in tool_requests:
            tid = tr.get("id")
            if isinstance(tid, str):
                existing_ids.add(tid)
        req_id = _gen_req_id(existing_ids)
        ts = _iso(now)
        row = {
            "id": req_id,
            "api_key_id": api_key_id,
            "tool_name": "get_tool_request",  # not in enum, but tool surface demands logging; keep as invoked name
            "status": status,
            "request_params": params if isinstance(params, dict) else {},
            "normalized_query": normalized_query,
            "result_summary": summary,
            "error_code": error_code,
            "error_message": (error_message[:4000] if isinstance(error_message, str) else error_message),
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": bool(cache_hit),
            "latency_ms": latency_ms,
            "created_at": ts,
            "updated_at": ts,
        }
        tool_requests.append(row)
        return row

    def _minute_ago(dt):
        return dt - datetime.timedelta(seconds=60)

    def _day_start_utc(dt):
        d = dt.astimezone(datetime.timezone.utc).date()
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _enforce_limits(tool_requests, key_row):
        if not key_row:
            return False, ("UNAUTHORIZED", "Invalid API key.")
        if key_row.get("status") != "active":
            return False, ("RATE_LIMIT", "API key is not active. Contact support to restore access.", "api_key_inactive", None)

        rpm = key_row.get("requests_per_minute")
        rpd = key_row.get("requests_per_day")
        if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
            # key misconfigured; treat as unauthorized/unusable
            return False, ("UNAUTHORIZED", "API key is not authorized for requests.", "api_key_invalid", None)

        win_start = _minute_ago(now)
        day_start = _day_start_utc(now)

        cnt_min = 0
        cnt_day = 0
        for tr in tool_requests:
            if tr.get("api_key_id") != key_row.get("id"):
                continue
            created = _parse_dt(tr.get("created_at"))
            if not created:
                continue
            if created >= day_start:
                cnt_day += 1
            if created >= win_start:
                cnt_min += 1

        if cnt_min >= rpm:
            # approximate retry-after as seconds until 60s window clears based on earliest request in window
            earliest = None
            for tr in tool_requests:
                if tr.get("api_key_id") != key_row.get("id"):
                    continue
                created = _parse_dt(tr.get("created_at"))
                if created and created >= win_start:
                    if earliest is None or created < earliest:
                        earliest = created
            retry_after = None
            if earliest:
                retry_after = max(0, int(60 - (now - earliest).total_seconds()))
            return False, ("RATE_LIMIT", f"Rate limit exceeded. Retry after {retry_after if retry_after is not None else 60} seconds.", "rate_limit_rpm", retry_after)

        if cnt_day >= rpd:
            return False, ("QUOTA_EXCEEDED", "Daily request quota exceeded. Retry after UTC day rollover.", "rate_limit_rpd", None)

        return True, None

    # -------- validate inputs --------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")

    keys = _load("api_keys.json")
    if isinstance(keys, dict) and "rows" in keys:
        keys = keys["rows"]
    if not isinstance(keys, list):
        keys = []

    tool_requests = _load("tool_requests.json")
    if isinstance(tool_requests, dict) and "rows" in tool_requests:
        tool_requests = tool_requests["rows"]
    if not isinstance(tool_requests, list):
        tool_requests = []

    key_row = _match_api_key_row(keys, api_key)

    ok, lim = _enforce_limits(tool_requests, key_row)
    # Always create exactly one tool_requests row per invocation.
    # If auth fails entirely (no key_row), log with dummy api_key_id if possible; otherwise refuse without logging.
    api_key_id_for_log = key_row.get("id") if key_row else None
    if not api_key_id_for_log:
        # cannot satisfy schema api_key_id non-null; choose any key that matches presented string by id/prefix already failed
        # Per contract: return UNAUTHORIZED only if no combination can serve the call.
        # Here, no matching key => cannot log valid row => return UNAUTHORIZED.
        return _err("UNAUTHORIZED", "Invalid API key.")

    if not ok:
        code, msg, ecode, retry_after = lim
        latency_ms = int((time.time() - t0) * 1000)
        _log_tool_request(
            tool_requests,
            api_key_id_for_log,
            "rate_limited",
            {"api_key": api_key, "id": id},
            normalized_query=id.strip(),
            summary=None,
            error_code=ecode,
            error_message=msg,
            cache_hit=False,
            latency_ms=latency_ms,
        )
        _save("tool_requests.json", tool_requests)
        extra = {}
        if retry_after is not None:
            extra["retry_after_seconds"] = retry_after
        return _err(code, msg, **extra)

    # -------- perform read --------
    target_id = id.strip()
    found = None
    for tr in tool_requests:
        if tr.get("id") == target_id and tr.get("api_key_id") == key_row.get("id"):
            found = tr
            break

    latency_ms = int((time.time() - t0) * 1000)

    if not found:
        _log_tool_request(
            tool_requests,
            key_row.get("id"),
            "failed",
            {"api_key": api_key, "id": id},
            normalized_query=target_id,
            summary={"found": False},
            error_code="not_found",
            error_message="Tool request not found",
            cache_hit=False,
            latency_ms=latency_ms,
        )
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Tool request not found")

    # success: update key last_used_at and log succeeded
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", keys)

    _log_tool_request(
        tool_requests,
        key_row.get("id"),
        "succeeded",
        {"api_key": api_key, "id": id},
        normalized_query=target_id,
        summary={"found": True, "tool_name": found.get("tool_name"), "status": found.get("status")},
        cache_hit=True,
        latency_ms=latency_ms,
    )
    _save("tool_requests.json", tool_requests)

    # Return stored record envelope (no fabrication)
    return {
        "tool_request": found,
        "meta": {
            "requested_id": target_id,
            "owned_by_api_key_id": key_row.get("id"),
        },
    }

def update_api_key(api_key, id, label=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0119000" if __import__("os").path.isdir("./environment_mix/0119000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _canon_key_prefix(k):
        if not isinstance(k, str):
            return None
        return k.strip()[:8]

    def _find_key(keys, presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        p = presented.strip()
        for r in keys:
            if r.get("id") == p:
                return r
        pref = _canon_key_prefix(p)
        if pref:
            for r in keys:
                if r.get("key_prefix") == pref:
                    return r
        return None

    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a string")
    if label is not None and (not isinstance(label, str) or not label.strip()):
        return _err("VALIDATION_ERROR", "label must be a non-empty string when provided")
    allowed_status = {"active", "suspended", "revoked"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status", allowed=sorted(list(allowed_status)))

    # Authenticate caller key
    caller = _find_key(api_keys, api_key)
    if not caller:
        return _err("UNAUTHORIZED", "Invalid API key")

    caller_id = caller.get("id")

    # Quota/rate limit check for this call; also reject non-active (rule says rate_limited for non-active on any request)
    now = _now_utc()
    minute_ago = now - datetime.timedelta(minutes=1)
    utc_day = now.date().isoformat()

    rpm = caller.get("requests_per_minute")
    rpd = caller.get("requests_per_day")
    if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
        return _err("VALIDATION_ERROR", "API key quotas are misconfigured")

    def _parse_created(r):
        v = r.get("created_at")
        if isinstance(v, str):
            s = v.strip()
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    minute_count = 0
    day_count = 0
    for r in tool_requests:
        if r.get("api_key_id") != caller_id:
            continue
        dt = _parse_created(r)
        if not dt:
            continue
        if dt >= minute_ago:
            minute_count += 1
        if dt.date().isoformat() == utc_day:
            day_count += 1

    def _log_rate_limited(code, msg):
        tr = {
            "id": _new_id("trq"),
            "api_key_id": caller_id,
            "tool_name": "ip_lookup",  # schema enum limitation
            "status": "rate_limited",
            "request_params": {"api_key": api_key, "id": id, "label": label, "status": status},
            "normalized_query": None,
            "result_summary": None,
            "error_code": code,
            "error_message": msg[:4000],
            "upstream_provider": "shodan",
            "upstream_request_id": None,
            "cache_hit": False,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now.isoformat(),
            "updated_at": now.isoformat(),
        }
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err(code, msg)

    if caller.get("status") != "active":
        return _log_rate_limited("RATE_LIMIT", "API key is not active")
    if minute_count >= rpm:
        return _log_rate_limited("RATE_LIMIT", "Per-minute rate limit exceeded")
    if day_count >= rpd:
        return _log_rate_limited("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Log invocation (queued->running->succeeded/failed)
    tr_id = _new_id("trq")
    req_row = {
        "id": tr_id,
        "api_key_id": caller_id,
        "tool_name": "ip_lookup",  # schema enum limitation
        "status": "queued",
        "request_params": {"api_key": api_key, "id": id, "label": label, "status": status},
        "normalized_query": id.strip(),
        "result_summary": None,
        "error_code": None,
        "error_message": None,
        "upstream_provider": "shodan",
        "upstream_request_id": None,
        "cache_hit": True,
        "latency_ms": None,
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    req_row["status"] = "running"
    req_row["updated_at"] = _now_utc().isoformat()
    _save("tool_requests.json", tool_requests)

    # Find target key
    target = None
    for r in api_keys:
        if r.get("id") == id:
            target = r
            break
    if not target:
        req_row["status"] = "failed"
        req_row["error_code"] = "NOT_FOUND"
        req_row["error_message"] = "API key not found"
        req_row["updated_at"] = _now_utc().isoformat()
        req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "API key not found")

    # Authorization: caller must be owner of target key
    # If owner fields are missing, treat as not authorized unless it's the same key record.
    if target.get("id") != caller_id:
        if not target.get("owner") or not caller.get("owner") or target.get("owner") != caller.get("owner"):
            req_row["status"] = "failed"
            req_row["error_code"] = "UNAUTHORIZED"
            req_row["error_message"] = "Not permitted to update this API key"
            req_row["updated_at"] = _now_utc().isoformat()
            req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
            _save("tool_requests.json", tool_requests)
            return _err("UNAUTHORIZED", "Not permitted to update this API key")

    # Apply updates
    changed = False
    if label is not None:
        target["label"] = label
        changed = True

    if status is not None:
        cur = target.get("status")
        transitions = {"active": ["suspended", "revoked"], "suspended": ["active", "revoked"], "revoked": []}
        if cur not in transitions:
            req_row["status"] = "failed"
            req_row["error_code"] = "INVALID_TRANSITION"
            req_row["error_message"] = "Current status is invalid"
            req_row["updated_at"] = _now_utc().isoformat()
            req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
            _save("tool_requests.json", tool_requests)
            return _err("INVALID_TRANSITION", "Current status is invalid")
        if status != cur:
            if status not in transitions[cur]:
                req_row["status"] = "failed"
                req_row["error_code"] = "INVALID_TRANSITION"
                req_row["error_message"] = f"Illegal status transition {cur} -> {status}"
                req_row["updated_at"] = _now_utc().isoformat()
                req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
                _save("tool_requests.json", tool_requests)
                return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}")
            target["status"] = status
            changed = True

    if not changed:
        # No success without effect
        req_row["status"] = "failed"
        req_row["error_code"] = "VALIDATION_ERROR"
        req_row["error_message"] = "No changes requested"
        req_row["updated_at"] = _now_utc().isoformat()
        req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        _save("tool_requests.json", tool_requests)
        return _err("VALIDATION_ERROR", "No changes requested")

    target["updated_at"] = _now_utc().isoformat()
    _save("api_keys.json", api_keys)

    req_row["status"] = "succeeded"
    req_row["updated_at"] = _now_utc().isoformat()
    req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
    req_row["result_summary"] = {"updated_api_key_id": target.get("id"), "new_status": target.get("status"), "label": target.get("label")}
    _save("tool_requests.json", tool_requests)

    caller["last_used_at"] = _now_utc().isoformat()
    caller["updated_at"] = _now_utc().isoformat()
    _save("api_keys.json", api_keys)

    return {"data": target}
